# (feastDate, English name, Turkish name, Turkish description, Turkish patronOf) - May to August, from saints_daily_en_2.py
DATA = [
    ("May 1", "Saint Joseph the Worker", "İşçi Aziz Yusuf", "Papa XII. Pius bu bayramı 1955'te marangoz Yusuf'u ve insan emeğinin onurunu anmak için koydu. Yusuf, sevgiyle sunulan sıradan emeğin kutsallığa giden bir yol olduğunu gösterir.", "İşçiler, zanaatkârlar, babalar"),
    ("May 3", "Saints Philip and James the Apostles", "Havari Aziz Filipus ve Aziz Yakup", "On iki havariden ikisi. Filipus, Nathanael'i İsa'ya getirdi ve 'bize Baba'yı göster' dedi; Küçük Yakup Kudüs kilisesine önderlik etti. İkisi de iman uğruna şehit oldu.", "Şapkacılar, pastacılar, Kudüs Kilisesi"),
    ("May 4", "Saint Florian", "Aziz Florian", "304'te Hıristiyanlara zulmetmeyi reddettiği için Avusturya'da şehit edilen Romalı subay. Yangına karşı korunma için anılır; itfaiyecilerin koruyucusudur.", "İtfaiyeciler, yangın tehlikesindekiler"),
    ("May 5", "Saint Angelus of Jerusalem", "Kudüslü Aziz Angelus", "On üçüncü yüzyılda Karmelit keşiş ve vaiz; Yahudilikten dönmüş, Sicilya'da vaaz vermiştir. Günah konusunda alenen uyardığı bir adam tarafından öldürüldü.", "Karmelitler, vaizler"),
    ("May 6", "Saint John before the Latin Gate", "Latin Kapısı Önündeki Aziz Yuhanna", "Gelenek, Yuhanna'nın Domitianus zulmü sırasında Roma'da Latin Kapısı'nda kaynayan yağa atıldığını ve sağ çıktığını anlatır. Roma'daki bir kilise yeri işaretler.", "Tehlikedekiler, zulüm gören Hıristiyanlar"),
    ("May 7", "Saint Rose Venerini", "Aziz Rose Venerini", "İtalya'da kızlar için ilk devlet okullarını açan İtalyan öğretmen (1656-1728). Öğretmenler yetiştirdi ve Filippini Öğretmen Rahibeleri'ni kurdu; nazik azmiyle bilinir.", "Öğretmenler, kadın eğitimi"),
    ("May 8", "Julian of Norwich", "Norwichli Julian", "Bir kadın tarafından yazılan, İngilizcedeki en eski eser olan 'İlahi Sevginin Vahiyleri'ni yazan İngiliz münzevi (1342-yaklaşık 1416). 'Her şey iyi olacak' sözü kuşaklara teselli verdi.", "Mistikler, şüphe ve sıkıntıdakiler"),
    ("May 9", "Saint Pachomius", "Aziz Pachomius", "Toplu manastır yaşamının Mısırlı kurucusu (yaklaşık 292-348). Münzevileri bir kuralla yönetilen manastırlarda topladı ve Doğu ile Batı'daki Hıristiyan manastır hayatını şekillendirdi.", "Keşişler, cemaat yaşamı"),
    ("May 11", "Saint Ignatius of Laconi", "Laconi'li Aziz Ignatius", "Manastırı için kırk yıl dilencilik yapan Sardinyalı Kapuçin kardeş (1701-1781). Çocuklar ve yoksullar alçakgönüllülüğü ve yumuşak ruhu yüzünden onu sevdi.", "Dilenciler, alçakgönüllüler, Sardinya"),
    ("May 12", "Saint Pancras of Rome", "Romalı Aziz Pancras", "Putlara kurban sunmayı reddettiği için yaklaşık 304'te on dört yaşında ölen genç Romalı şehit. Londra'daki kilisesi semte adını verdi.", "Çocuklar, gençler, yemin edenler"),
    ("May 13", "Our Lady of Fatima", "Fatima Meryemi", "13 Mayıs 1917'de Meryem, Portekiz'in Fatima kasabasında üç çoban çocuğa göründü; dünyada barış için dua, tövbe ve her gün Tespih istedi.", "Barış, Tespih, Portekiz"),
    ("May 14", "Saint Matthias the Apostle", "Havari Aziz Matyas", "Elçilerin İşleri'ne göre, On İkiler arasında Yahuda'nın yerini almak üzere kurayla seçildi. İsa'yı vaftizinden itibaren izlemiş ve dirilişe tanık olmuştu.", "Gözden kaçmış hissedenler, terziler"),
    ("May 16", "Saint Brendan the Navigator", "Denizci Aziz Brendan", "Manastırlar kuran ve gelenek göre arkadaşlarıyla 'Azizlerin Vaat Edilmiş Toprağı'nı aramak için yedi yıl batıya yelken açan İrlandalı başrahip (yaklaşık 484-577).", "Denizciler, yolcular, İrlanda"),
    ("May 17", "Saint Paschal Baylon", "Aziz Paschal Baylon", "Kapıcı, çoban ve bekçi olarak çalışan İspanyol Fransiskan kardeş (1540-1592). Efkaristiya'ya derin bağlılığı vardı; Efkaristiya kongrelerinin koruyucusudur.", "Efkaristiya'ya bağlılık, aşçılar"),
    ("May 18", "Pope Saint John I", "Papa Aziz Yuhanna I", "523-526 arasında papa. İmparatordan Ariusçulara zulmü durdurmasını istemek için İstanbul'a gitti. Got kralı Theodoric tarafından hapsedildi ve hapiste öldü.", "Mahkûmlar, barış yapıcılar"),
    ("May 19", "Saint Celestine V", "Aziz Celestine V", "1294'te 79 yaşında papa seçilen münzevi. Göreve boğulup beş ay sonra istifa ederek duaya döndü; bu eylem Kilise'yi o günden beri düşündürmüştür.", "Münzeviler, alçakgönüllülükle görevi bırakanlar"),
    ("May 20", "Saint Bernardine of Siena", "Sienalı Aziz Bernardino", "İtalya'da yorulmadan vaaz veren, İsa'nın Kutsal Adı'na bağlılığı teşvik eden ve veba kurbanlarına bakan İtalyan Fransiskan (1380-1444). İnsanları barışmaya çağırdı.", "Vaizler, reklamcılar, konuşmacılar"),
    ("May 21", "Saint Christopher Magallanes and Companions", "Aziz Christopher Magallanes ve Arkadaşları", "1915-1937 arasında dinî zulüm sırasında öldürülen, çoğu rahip yirmi beş Meksikalı şehit. Çoğu 'Yaşasın Kral Mesih!' diye haykırarak ve celladlarını affederek öldü.", "Meksika, zulüm görenler"),
    ("May 23", "Saint Ivo of Kermartin", "Kermartin'li Aziz Ivo", "'Yoksulların avukatı' olarak bilinen Breton yargıç ve rahip (1253-1303). Yoksullara bedava adalet dağıttı, anlaşmazlıkları çözdü, sade yaşadı ve yemeğini açlarla paylaştı.", "Avukatlar, yargıçlar, yoksullar"),
    ("May 25", "Saint Bede the Venerable", "Saygıdeğer Aziz Bede", "'İngiliz Halkının Kilise Tarihi'ni ve pek çok tefsiri yazan Jarrow'lu İngiliz keşiş (yaklaşık 673-735). Kilise Doktoru unvanını taşıyan tek İngiliz'dir.", "Tarihçiler, bilginler, öğretmenler"),
    ("May 28", "Saint Bernard of Menthon", "Menthon'lu Aziz Bernard", "Adını taşıyan Alp geçitlerinde hacıları ve yolcuları barındıran hospisler kuran Alp başdiyakozu (yaklaşık 1020-1081). Ünlü kurtarma köpeklerine daha sonra adı verildi.", "Dağcılar, kayakçılar, yolcular"),
    ("May 29", "Saint Maximinus of Trier", "Trier'li Aziz Maximinus", "Sürgündeki Aziz Athanasius'u barındıran dördüncü yüzyıl Trier piskoposu. Galya'da İznik inancını savundu ve konukseverliğiyle saygı gördü.", "Kanaat önderleri, ev sahipleri"),
    ("May 31", "The Visitation of the Blessed Virgin Mary", "Meryem'in Elizabet'i Ziyareti", "Yeni hamile kalan Meryem, kuzeni Elizabet'i ziyarete gider. Elizabet onu 'kadınlar arasında kutsanmış' diye selamlar, Meryem ise büyük övgü şarkısı Magnificat ile karşılık verir.", "Hamile kadınlar, başkalarına hizmet edenler"),

    ("June 1", "Saint Justin Martyr", "Şehit Aziz Justin", "Roma dinleyicilerine imanı açıklayan ve imparator önünde inananları savunan filozof, sonra Hıristiyan öğretmen (yaklaşık 100-165). Roma'da başı kesildi.", "Filozoflar, savunmacılar"),
    ("June 2", "Saints Marcellinus and Peter", "Aziz Marcellinus ve Aziz Petrus", "Diocletianus altında yaklaşık 304'te Roma'da öldürülen bir rahip ve bir şeytan kovucu. Roma Kanonu'nda anılırlar; hikâyelerini sonradan din değiştiren cellatları anlatır.", "Erken Kilise şehitleri"),
    ("June 3", "Saint Charles Lwanga and Companions", "Aziz Charles Lwanga ve Arkadaşları", "1886'da imanlarından vazgeçmeyi reddettikleri için şehit edilen, saray uşağı yirmi iki genç Ugandalı. Afrika'nın Büyük Göller bölgesinin ilk şehitleri olarak onurlandırılırlar.", "Uganda, Afrikalı gençler, din değiştirenler"),
    ("June 4", "Saint Francis Caracciolo", "Aziz Francis Caracciolo", "Küçük Düzenli Din Adamları'nı birlikte kuran ve Kutsal Ekmek'e sürekli tapınmayı teşvik eden İtalyan rahip (1563-1608). Mahkûmlara ve yoksullara hizmet etti.", "Efkaristiya'ya tapınma, aşçılar"),
    ("June 6", "Saint Norbert of Xanten", "Xanten'li Aziz Norbert", "Ölümcül bir yıldırım çarpmasından sonra dönüşen ve Premontre kanonlarını kuran Alman piskopos (yaklaşık 1075-1134). Efkaristiya'ya bağlılığı teşvik etti.", "Reformcular, hamile kadınlar"),
    ("June 7", "Saint Antony Mary Gianelli", "Aziz Antony Mary Gianelli", "Bobbio'nun İtalyan piskoposu ve Mary Dell'Orto Rahibeleri'nin kurucusu (1789-1846). Kıtlık sırasında ihtiyaç sahiplerine baktı ve halkının imanını güçlendirdi.", "Piskoposlar, ihtiyaç sahipleri"),
    ("June 8", "Saint William of York", "Yorklu Aziz William", "Kilise siyaseti yüzünden iki kez görevden alınıp iki kez dönen İngiliz başpiskopos (ö. 1154). Yumuşaklığı ve York'un yoksullarına bakışıyla sevildi.", "York, haksızlığa uğrayanlar"),
    ("June 10", "Saint Henry of Treviso", "Treviso'lu Aziz Henry", "Gündelikçi olarak çalışan ve yoksulluk içinde yaşayan İtalyan meslekten olmayan kişi (ö. 1315). Her gün katedralde dua etti; öldükten sonra Treviso halkı onu aziz olarak onurlandırdı.", "Gündelikçiler, yoksullar"),
    ("June 12", "Pope Saint Leo III", "Papa Aziz Leo III", "800 Noel'inde Charlemagne'ı imparator olarak taçlandıran, 795-816 arasında papa. Roma'da şiddetli muhalefetle karşılaştı; kilise inşa etmesi ve imanı savunmasıyla bilinir.", "Papazlar, muhalefetle karşılaşanlar"),
    ("June 14", "Saint Methodius I of Constantinople", "İstanbullu Aziz Methodius I", "Kutsal tasvirleri savunduğu için zulüm gören ve Kilise'yi 843'teki 'Ortodoksluğun Zaferi'ne ulaştıran İstanbul patriği (yaklaşık 788-847).", "Kutsal sanat savunucuları"),
    ("June 15", "Saint Germaine Cousin", "Aziz Germaine Cousin", "Elinde engel olan, ailesince kötü muamele gören Fransız çoban kızı (1579-1601). Kıt ekmeğinden yoksullara verdi ve her gün büyük bir imanla Ayin'de dua etti.", "Kötü muamele görenler, engelliler, çobanlar"),
    ("June 16", "Saint John Francis Regis", "Aziz John Francis Regis", "Cevennes dağlarında halk misyonları vaaz eden, yoksullara ve hastalara bakan, ihtiyaç sahipleri için barınaklar kuran Fransız Cizvit (1597-1640).", "Sosyal hizmet uzmanları, dantel işçileri"),
    ("June 17", "Saint Albert Chmielowski", "Aziz Albert Chmielowski", "Sanatı bırakıp Krakow'un yoksullarına hizmet eden Polonyalı ressam ve asker (1845-1916). Albertin Kardeşler ve Rahibeler'i kurdu.", "Evsizler, sanatçılar, her şeyi bırakanlar"),
    ("June 18", "Saints Mark and Marcellian", "Aziz Markus ve Aziz Marcellianus", "Yaklaşık 286'da Roma'da şehit edilen ikiz kardeşler. Gelenek, sütunlara bağlanıp çivilerle delindiklerini ve ölürken övgü söylediklerini anlatır; Via Ardeatina'ya gömüldüler.", "İkizler, şehitler"),
    ("June 19", "Saint Romuald", "Aziz Romuald", "Camaldoli münzevilerini kuran ve manastır yaşamını yenilemek için on yıllarca yolculuk eden İtalyan keşiş (yaklaşık 951-1027). Mezmurlara nazik, tefekkür dolu bir yaklaşım öğretti.", "Münzeviler, tefekkür edenler"),
    ("June 20", "Pope Saint Silverius", "Papa Aziz Silverius", "536-537 arasında papa. Siyasi entrikalar sonucu görevden alınıp küçük bir adaya sürüldü ve zorluk içinde öldü. İman uğruna şehit olarak onurlandırılır.", "Haksız yere sürgün edilenler"),
    ("June 21", "Saint Aloysius Gonzaga", "Aziz Aloysius Gonzaga", "Prenslik mirasından vazgeçip İsa Cemiyeti'ne giren İtalyan Cizvit (1568-1591). Roma'da veba kurbanlarına bakarken 23 yaşında öldü.", "Gençler, öğrenciler, veba hastaları"),
    ("June 23", "Saint Joseph Cafasso", "Aziz Joseph Cafasso", "Torino'da genç rahipleri yetiştiren ve mahkûmları ziyaret eden İtalyan rahip (1811-1860). İdam mahkûmlarıyla darağacına kadar yürüdü; cezaevi papazlarının koruyucusudur.", "Cezaevi papazları, mahkûmlar"),
    ("June 25", "Saint Maximus of Turin", "Torino'lu Aziz Maximus", "Kısa ve canlı vaazları vaaz verme rehberi olarak günümüze ulaşan Torino piskoposu (ö. yaklaşık 465). İstila çalkantısı içinde halkını Mesih'i aramaya teşvik etti.", "Vaizler, papazlar"),
    ("June 26", "Saint Josemaria Escriva", "Aziz Josemaria Escriva", "Opus Dei'yi kuran ve sıradan işin ve gündelik hayatın herkese açık bir kutsallık yolu olduğunu öğreten İspanyol rahip (1902-1975).", "Meslekten olmayan Hıristiyanlar, işçiler, işin kutsanması"),
    ("June 30", "The First Martyrs of the Church of Rome", "Roma Kilisesi'nin İlk Şehitleri", "64'te Roma'nın büyük yangınından sonra Nero döneminde ölen Hıristiyanlar. Roma'nın ilk şehit meyveleriydiler; tanıklıkları imanın şehirde büyümesinin yolunu hazırladı.", "Zulüm gören Hıristiyanlar"),

    ("July 1", "Saint Junipero Serra", "Aziz Junipero Serra", "Kaliforniya'da misyonlar kuran İspanyol Fransiskan (1713-1784). Mirası tartışmalıdır, ancak hastalığa rağmen çobanlık hizmetine adanmışlığı ve yorulmak bilmez yolculuğuyla anılır.", "Kaliforniya, misyonerler"),
    ("July 2", "Saints Processus and Martinian", "Aziz Processus ve Aziz Martinian", "Roma'daki Mamertine hapishanesinde Aziz Petrus'un gardiyanları olan, onun tarafından dönüştürülen ve vaftiz edilen iki kişi. Şehit edildiler; kalıntıları Aziz Petrus Bazilikası'nda durur.", "Cezaevi gardiyanları, din değiştirenler"),
    ("July 5", "Saint Anthony Zaccaria", "Aziz Anthony Zaccaria", "Hekimken rahip olan, Barnabitleri kuran ve sık komünyonu ve Aziz Pavlus'a bağlılığı teşvik eden İtalyan (1502-1539). Arkadaşlarını 'Mesih için aptal olmaya' çağırdı.", "Hekimler, rahipler, reformcular"),
    ("July 7", "Saint Willibald", "Aziz Willibald", "Kutsal Topraklar'a hac yapan, sonra Aziz Boniface ile Almanya'da hizmet eden İngiliz piskopos (yaklaşık 700-787). Heidenheim Manastırı'nı kurdu ve Eichstatt piskoposu oldu.", "Hacılar, yolcular"),
    ("July 8", "Saints Priscilla and Aquila", "Aziz Priskilla ve Aziz Akila", "Korint ve Efes'te Pavlus'u konuk eden ve Apollos'a öğreten çadırcı bir çift. Evlerini kilise olarak açtılar ve Pavlus için canlarını tehlikeye attılar.", "Evli çiftler, ev sahipleri, çadırcılar"),
    ("July 9", "Saint Augustine Zhao Rong and Companions", "Aziz Augustine Zhao Rong ve Arkadaşları", "On yedinci ve on dokuzuncu yüzyıllar arasında öldürülen, piskoposlardan köylülere uzanan 120 Çinli şehit. Aralarında zulüm altında imanı koruyan birçok sıradan kadın ve erkek vardı.", "Çin, zulüm görenler"),
    ("July 10", "Saints Rufina and Secunda", "Aziz Rufina ve Aziz Secunda", "Valerianus zulmü sırasında yaklaşık 257'de Roma'da şehit düşen kız kardeşler. Palmiyeler ve merhem kavanozlarıyla resmedilirler ve Lateran katedralinde onurlandırılırlar.", "Kız kardeşler, şehitler"),
    ("July 13", "Saint Henry II", "Aziz Henry II", "Saltanatını Kilise'yi desteklemeye, Bamberg piskoposluğunu kurmaya ve manastır reformunu teşvik etmeye adayan Alman imparator (973-1024). Karısı Aziz Cunegund ile evlilik içinde bekâr yaşadı.", "Hükümdarlar, evli çiftler, engelliler"),
    ("July 16", "Our Lady of Mount Carmel", "Karmel Dağı Meryemi", "Kutsal Topraklar'daki Karmel Dağı'nda kurulan Karmelit tarikatının koruyucusu Meryem'i onurlandıran bayram. Bağlılıkla takılan kahverengi skapüler onun korumasını hatırlatır.", "Karmelitler, skapüler takanlar"),
    ("July 17", "The Martyrs of Compiegne", "Compiegne Şehitleri", "Fransız Devrimi sırasında 17 Temmuz 1794'te Paris'te giyotinle idam edilen on altı Karmelit rahibe. İdam kürsüsüne şarkı söyleyerek yürüdüler ve canlarını barış için sundular.", "Rahibeler, çatışma zamanlarında barış"),
    ("July 18", "Saint Symphorosa and Her Seven Sons", "Aziz Symphorosa ve Yedi Oğlu", "Putlara kurban sunmayı reddettikleri için yaklaşık 135'te yedi oğluyla birlikte şehit edilen Romalı dul. Gelenek, her oğlunu ölürken cesaretlendirdiğini söyler.", "Anneler, aileler"),
    ("July 19", "Saint Macrina the Younger", "Genç Aziz Macrina", "Aile evini bir dua topluluğuna dönüştüren Kapadokyalı rahibe (yaklaşık 330-379). Kardeşleri Basil ve Nyssalı Gregory'nin öğretmeni ve rehberiydi.", "Öğretmenler, manastırdaki kız kardeşler"),
    ("July 20", "Saint Apollinaris of Ravenna", "Ravennalı Aziz Apollinaris", "Gelenek, Aziz Petrus'un öğrencisi olan, bölgede İncil'i yayan ve şehit edilen Ravenna'nın ilk piskoposu olduğunu söyler. Sant'Apollinare in Classe Bazilikası onu onurlandırır.", "Ravenna, piskoposlar, sara hastaları"),
    ("July 21", "Saint Lawrence of Brindisi", "Brindisili Aziz Lawrence", "Birçok dil konuşan ve Avrupa'yı dolaşarak vaaz veren İtalyan Kapuçin (1559-1619). İmparatorluk ordularında papaz olarak görev yaptı; Kilise Doktoru ilan edildi.", "Vaizler, dilbilimciler, barış yapıcılar"),
    ("July 27", "Saint Pantaleon", "Aziz Pantaleon", "Yaklaşık 305'te şehit edilen İzmitli hekim. Adı 'her şeye merhametli' anlamına gelir; ücret almadan şifa veren 'Kutsal Ücretsiz Hekimler'den biridir.", "Hekimler, hastalar"),
    ("July 29", "Saints Martha, Mary and Lazarus", "Aziz Marta, Aziz Meryem ve Aziz Lazar", "Evleri İsa'yı ağırlayan Beytanyalı kardeşler. Marta hizmet etti, Meryem dinledi, Lazar ölümden diriltildi. Birlikte Mesih'le dostluğu gösterirler.", "Ev sahipleri, hizmet edenler ve dua edenler"),

    ("August 2", "Saint Eusebius of Vercelli", "Vercelli'li Aziz Eusebius", "Din adamlarının ortak yaşadığı bir topluluk kuran ve Ariusçu yöneticilere karşı İznik inancını savunduğu için sürgün edilen Vercelli piskoposu (yaklaşık 283-371).", "Piskoposlar, inanç bildirisinin savunucuları"),
    ("August 3", "Saint Nicodemus", "Aziz Nikodemus", "İsa'yı geceleyin ziyaret eden, onu Sanhedrin önünde savunan ve Arimatyalı Yusuf'un bedenini gömmesine yardım eden bir Ferisi. Sessiz cesareti yavaş yavaş açık imana dönüştü.", "Tanrı'yı gizlice arayanlar"),
    ("August 5", "Dedication of the Basilica of Saint Mary Major", "Santa Maria Maggiore Bazilikası'nın Kutsanışı", "Efes Konsili'nden sonra Roma'da inşa edilen, Batı'da Meryem'e adanmış en eski kilise. Bayram, Esquilino Tepesi'ne yazın kar yağdığı geleneğini hatırlatır.", "Roma, Meryem'e bağlılık"),
    ("August 6", "The Transfiguration of the Lord", "Rab'bin Başkalaşımı", "Yüksek bir dağda İsa'nın yüzü güneş gibi parladı, Musa ve İlyas onunla göründü ve Baba'nın sesi 'Bu benim sevgili Oğlum' dedi. Gelecek yüceliğe bir bakıştır.", "Tanrı'ya doğru tırmananlar"),
    ("August 7", "Saint Cajetan", "Aziz Cajetan", "Din adamlarını yenilemek ve hastalara bakmak için Theatinleri kuran İtalyan rahip (1480-1547). Tanrı'nın takdirine tamamen güvenmeye inandı; yoksullara ve çaresizlere baktı.", "İşsizler, kumarbazlar, iş arayanlar"),
    ("August 12", "Saint Jane Frances de Chantal", "Aziz Jane Frances de Chantal", "Kocasının ölümünden sonra Aziz Francis de Sales'in dostu olan ve Ziyaret Rahibeleri'ni birlikte kuran Fransız soylu kadın (1572-1641).", "Dullar, ebeveynler, eşini kaybedenler"),
    ("August 13", "Saints Pontian and Hippolytus", "Aziz Pontianus ve Aziz Hippolytus", "Tartışan ama ikisi de Sardunya madenlerine sürüldüğünde barışan bir papa ve bir rahip-ilahiyatçı. İkisi de yaklaşık 235'te orada öldü; kalıntıları Roma'ya getirildi.", "Uzlaşma, bağışlayanlar"),
    ("August 16", "Saint Stephen of Hungary", "Macaristanlı Aziz István", "Halkını Hıristiyanlığa yönlendiren, piskoposluklar ve manastırlar kuran, yetimlere ve yoksullara bakan Macaristan'ın ilk kralı (yaklaşık 975-1038).", "Macaristan, krallar, taş ustaları"),
    ("August 17", "Saint Hyacinth of Poland", "Polonyalı Aziz Hyacinth", "İncil'i Polonya, Prusya ve Kiev'e taşıyan Polonyalı Dominikan (yaklaşık 1185-1257). Manastırlar kurdu; 'Polonya'nın Havarisi' olarak bilinir.", "Polonya, misyonerler"),
    ("August 18", "Saint Helena", "Aziz Helena", "İmparator Konstantin'in annesi (yaklaşık 250-330); yaşlılığında Kutsal Topraklar'a hac yaptı. Beytüllahim ve Zeytin Dağı'nda kiliseler yaptırdı ve İsa'nın yaşamının yerlerini onurlandırdı.", "Hacılar, arkeologlar, din değiştirenler"),
    ("August 19", "Saint John Eudes", "Aziz John Eudes", "Bölge misyonları vaaz eden, rahipleri yetiştirmek için Eudistleri kuran ve İsa ile Meryem'in Kalpleri'ne bağlılığı teşvik eden Fransız rahip (1601-1680).", "Rahipler, ruhban okulları"),
    ("August 21", "Pope Saint Pius X", "Papa Aziz Pius X", "1903-1914 arasında papa olan, asıl adı Giuseppe Sarto; sık komünyonu, küçük çocukların ilk komünyonunu ve ilmihal çalışmasını teşvik etti. Sade yaşadı.", "İlmihal öğretmenleri, ilk komünyon alanlar"),
    ("August 22", "The Queenship of the Blessed Virgin Mary", "Kutsal Bakire Meryem'in Kraliçeliği", "Meryem'i, Oğlu'nun yanında yücelikle taçlandırılmış cennet kraliçesi olarak kutlayan bayram. Onun kraliçeliği güç değil, merhamet ve hizmet kraliçeliğidir.", "Meryem'i onurlandıranlar"),
    ("August 25", "Saint Louis IX of France", "Fransa Kralı Aziz Louis IX", "Sainte-Chapelle'i yaptıran, yoksullara bakan, bir meşe ağacının altında hüküm veren ve haçlı seferinde ölen Fransa kralı (1214-1270). Hıristiyan bir hükümdarın örneğidir.", "Krallar, Üçüncü Tarikat Fransiskenleri, Fransız hükümdarlar"),
    ("August 26", "Saint Elizabeth Bichier des Ages", "Aziz Elizabeth Bichier des Ages", "Fransız Devrimi'nden sonra çocukları öğretmek ve yoksulları ve hastaları bakmak için Haç Kızları'nı kuran Fransız rahibe (1773-1838).", "Öğretmenler, kargaşadan sonra yeniden inşa edenler"),
    ("August 29", "The Passion of Saint John the Baptist", "Vaftizci Yahya'nın Şehitliği", "Kilise, Herodes'in evliliği hakkında hakikati söylediği için Vaftizci Yahya'nın başının kesilişini anar. Cesareti hakikate tanıklık için bir örnektir.", "Bedeli ne olursa olsun doğruyu söyleyenler"),
    ("August 30", "Saint Jeanne Jugan", "Aziz Jeanne Jugan", "Yaşlı, kör bir kadını evine alıp Yoksulların Küçük Rahibeleri'ni başlatan Fransız kadın (1792-1879); rahibeler bugün birçok ülkede yaşlılara bakıyor.", "Yaşlılar, bakıcılar"),
    ("August 31", "Saint Aidan of Lindisfarne", "Lindisfarne'li Aziz Aidan", "Lindisfarne manastırını kuran ve Northumbria'ya Hıristiyanlığı getiren İrlandalı keşiş (ö. 651). İnsanlarla buluşmak için yürüyerek gezdi ve yoksullara armağanlar dağıttı.", "Northumbria, misyonerler, müjdeciler"),
]
